// Copies defaults.json into defaults.js so the "Load defaults" button also works when index.html
// is opened straight from disk (browsers block reading JSON files over file://).
//
// Usage:  node tools/build-defaults.mjs

import { readFileSync, writeFileSync } from "node:fs";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const setup = JSON.parse(readFileSync(join(root, "defaults.json"), "utf8"));

writeFileSync(
  join(root, "defaults.js"),
  "// Generated by tools/build-defaults.mjs from defaults.json — do not edit by hand.\n" +
    "window.DEFAULT_SETUP = " + JSON.stringify(setup, null, 2) + ";\n"
);
console.log(`Wrote defaults.js (${setup.trusses.length} truss(es), room ${setup.width} × ${setup.depth} m)`);
